def run(_context):
    import re
    with open(r'C:\Users\Nanja\Desktop\PocketBox_Setup1.nc') as f:
        lines=f.read().splitlines()
    cur=None; zmin={}; zmax={}
    for l in lines:
        m=re.match(r'\((T[12] [^)]+)\)$', l)
        if m: cur=m.group(1); continue
        if cur:
            zz=re.search(r'Z(-?\d+\.?\d*)', l)
            if zz:
                v=float(zz.group(1))
                zmin[cur]=min(zmin.get(cur,1e9),v); zmax[cur]=max(zmax.get(cur,-1e9),v)
    for k in zmin: print(k, "Zmin",zmin[k], "Zmax",zmax[k])
    print("tail:")
    print("\n".join(lines[-25:]))
    return "ok"

