    lines = open(r'C:\Users\Nanja\Desktop\PocketBox_Setup1.nc').read().splitlines()
    print(len(lines))
    print("\n".join(lines[:30]))
    # check any G0 with Z below 11 (stock top = 0, so retract must be >= +10)
    bad=[]
    for i,l in enumerate(lines):
        if l.startswith('N') and ' G0' in ' '+l:
            z=re.search(r'Z(-?\d+\.?\d*)', l)
            if z and float(z.group(1)) < 10: bad.append((i,l))
